class RetirementRulesTests(unittest.TestCase):
 def setUp(self):
  self.manifest={'records':[],'deletionTombstones':copy.deepcopy(TOMBSTONES)}
  self.policy={'retiredRuntimeAssets':copy.deepcopy(POLICY_ROWS)}
 def test_exact_five_deleted_objects_leave_auditable_history(self):
  self.assertEqual(len(rr.validate_metadata(self.manifest,self.policy)),5)
  with tempfile.TemporaryDirectory() as temp:self.assertEqual(rr.audit_deleted_assets(temp,self.manifest,{},[]),[])
 def test_approval_forgery_active_records_and_stale_policy_are_rejected(self):
  for mutation in ['hash','approval','original','active','policy']:
   with self.subTest(mutation=mutation):
    m=copy.deepcopy(self.manifest);p=copy.deepcopy(self.policy)
    if mutation=='hash':m['deletionTombstones'][0]['sha256']='0'*64
    elif mutation=='approval':m['deletionTombstones'][0]['approvalEvidence']=''
    elif mutation=='original':m['deletionTombstones'][0]['originalRecord']['basis']='changed'
    elif mutation=='active':m['records'].append(copy.deepcopy(m['deletionTombstones'][0]['originalRecord']))
    else:p['retiredRuntimeAssets'][0]['state']='retired'
    with self.assertRaises(ValueError):rr.validate_metadata(m,p)
 def test_resurrection_alias_guid_aa_and_runtime_reference_are_detected(self):
  item=self.manifest['deletionTombstones'][0]
  with tempfile.TemporaryDirectory() as temp:
   root=Path(temp);meta=Path(str(root/item['path'])+'.meta');meta.parent.mkdir(parents=True);meta.write_text('orphan meta','utf8')
   self.assertTrue(rr.audit_deleted_assets(root,self.manifest,{},[]));meta.unlink()
   alias='Assets/Art/unpack/default/alias.png';self.assertTrue(rr.audit_deleted_assets(root,self.manifest,{alias:{'guid':item['guid']}},[]))
   self.assertTrue(rr.audit_deleted_assets(root,self.manifest,{},[{'guid':item['guid'],'group':'default','address':alias}]))
   consumer='Assets/Prefab/default/mainView/Bad.prefab';(root/consumer).parent.mkdir(parents=True);(root/consumer).write_text('guid: '+item['guid'],'utf8')
   findings=rr.audit_deleted_assets(root,self.manifest,{consumer:{'guid':'f'*32}},[])
   self.assertTrue(any(f['code']=='PACK_DELETED_REFERENCE' for f in findings))

if __name__=='__main__':unittest.main()
